    "title": "Digital Publication / Graphic Designer Expert",
    "description": "As our graphics workload is growing, we'd like to interview an experienced Digital Publication / Graphic Designer who can handle complete multi-page digital magazine layouts and fully clickable/interactive publications, including links to websites, emails, social media, videos, etc.\nOur projects include:\n- Fully clickable digital magazines\n- Digital Interactive Portfolios (DIP)\n- Company profiles and digital presentations\n- Ads and promotional graphics\nStrong graphic design is important, but candidates should ideally have previous experience with complete digital magazines or interactive publications, not mainly individual graphics or social media designs.\nOur requirements:\n- Have a strong graphic design portfolio.\n- Have experience creating interactive digital publications and clickable flipbooks with hyperlinks and buttons. This is a key requirement.\n- Have excellent written and spoken English.\n- Communicate proactively and provide regular project updates.\n- Be dependable, organized, and responsive.\n- Be comfortable collaborating via Zoom when needed.\n- Be interested in building a long-term working relationship.\n \nWe have several upcoming projects, so this could become an ongoing working relationship.\nOne thing that is particularly important to us is finding someone comfortable working collaboratively. Some assignments can be completed independently from a clear brief, while larger publication/layout projects require occasional short discussions and interaction as the work progresses.",
